## 5. Self-contained executable checker

The following JavaScript is the independently executed integer-arithmetic checker. It creates no files, uses no libraries or network requests, and performs the entire graph construction and clique search in memory.

```

const D = 2431, U = 1000, h = 60, t = 20;
const D2 = D * D, U2 = U * U;

const gap = (x,a,b) => Math.max(0,a-x,x-b);
const far = (x,a,b) =>
  Math.max(Math.abs(x-a),Math.abs(x-b));

function anchorOK([a,b,c,d]) {
  return [0,D].every(x =>
    gap(x,a,b)**2 + gap(0,c,d)**2 <= D2 &&
    far(x,a,b)**2 + far(0,c,d)**2 >= U2
  );
}

function pairOK([a,b,c,d],[e,f,g,k]) {
  const dx = Math.max(0,a-f,e-b);
  const dy = Math.max(0,c-k,g-d);
  const X = Math.max(Math.abs(a-f),Math.abs(b-e));
  const Y = Math.max(Math.abs(c-k),Math.abs(d-g));
  return dx*dx + dy*dy <= D2 &&
         X*X + Y*Y >= U2;
}

const squares = [], kids = [];

for(let i=0;i<=Math.ceil(D/h);i++)
for(let j=-Math.ceil(D/h);j<=Math.ceil(D/h);j++) {
  const x=i*h, y=j*h, R=[x,x+h,y,y+h];
  if(!anchorOK(R)) continue;

  squares.push(R);
  const list=[];

  for(let a=0;a<3;a++)
  for(let b=0;b<3;b++) {
    const xx=x+a*t, yy=y+b*t;
    const C=[xx,xx+t,yy,yy+t];
    if(anchorOK(C)) list.push(C);
  }
  kids.push(list);
}

const n=squares.length, W=Math.ceil(n/32);
const adj=Array.from(
  {length:n},()=>new Uint32Array(W)
);

let m=0, coarse=0;

for(let i=0;i<n;i++)
for(let j=i+1;j<n;j++) {
  if(!pairOK(squares[i],squares[j])) continue;
  coarse++;

  if(!kids[i].some(a =>
      kids[j].some(b => pairOK(a,b)))) continue;

  adj[i][j>>>5] |= 1<<(j&31);
  adj[j][i>>>5] |= 1<<(i&31);
  m++;
}

function first(A) {
  for(let w=0;w<W;w++) {
    const b=A[w];
    if(b) return (w<<5)+31-Math.clz32(b&-b);
  }
  return -1;
}

function pop(A) {
  let total=0;
  for(let v of A) {
    v -= (v>>>1)&0x55555555;
    v = (v&0x33333333)+
        ((v>>>2)&0x33333333);
    total += (((v+(v>>>4))&0x0f0f0f0f)*
              0x01010101)>>>24;
  }
  return total;
}

// Greedy proper coloring of the candidate graph.
function coloring(P) {
  const left=P.slice(), order=[], color=[];
  let shade=0;

  while(first(left)!==-1) {
    shade++;
    const available=left.slice();
    let v;

    while((v=first(available))!==-1) {
      order.push(v);
      color.push(shade);
      left[v>>>5] &= ~(1<<(v&31));

      for(let w=0;w<W;w++)
        available[w] &= ~adj[v][w];

      available[v>>>5] &= ~(1<<(v&31));
    }
  }
  return {order,color,shade};
}

let calls=0;

function hasK7(P,depth=0) {
  calls++;

  if(depth+pop(P)<7) return false;
  if(depth===6) return true;

  const {order,color,shade}=coloring(P);
  if(depth+shade<7) return false;

  for(let i=order.length-1;i>=0;i--) {
    if(depth+color[i]<7) return false;

    const v=order[i];
    const Q=new Uint32Array(W);

    for(let w=0;w<W;w++)
      Q[w]=P[w]&adj[v][w];

    if(hasK7(Q,depth+1)) return true;

    P[v>>>5] &= ~(1<<(v&31));
  }
  return false;
}

const all=new Uint32Array(W);
for(let v=0;v<n;v++)
  all[v>>>5] |= 1<<(v&31);

const result={
  vertices:n,
  coarseEdges:coarse,
  refinedEdges:m,
  hasK7:hasK7(all),
  calls
};

console.log(result);

```


